    def format_www_authenticate_header_value(self, in_: str, name: str) -> str:
        return f'ApiKey in="{in_}", name="{name}"'

    def check_api_key(self, api_key: Optional[str], auto_error: bool, not_authenticated_status_code: Optional[int] = None) -> Optional[str]:
        if not api_key:
            if auto_error:
                status_code = not_authenticated_status_code or HTTP_401_UNAUTHORIZED
                headers = {}
                if status_code == HTTP_401_UNAUTHORIZED:
                    headers["WWW-Authenticate"] = self.format_www_authenticate_header_value(
                        self.model.in_, self.model.name
                    )
                raise HTTPException(
                    status_code=status_code, detail="Not authenticated", headers=headers
                )
            return None
        return api_key

